 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';
import { gsap } from 'gsap';

const PIXELS_PER_UNIT = 320;

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Quaternion, Vector3 } = THREE;

  const group = new Group();
  group.userData.handlers = {};

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const region = config.intent?.visualSpec?.atlasRegion ?? config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };

  const width = (region.w ?? 512) / PIXELS_PER_UNIT;
  const height = (region.h ?? 320) / PIXELS_PER_UNIT;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  material.color.set(colors.paper ?? '#e8ecf2');

  const mesh = new Mesh(geometry, material);

  const _parentQ = new Quaternion();
  const _parentP = new Vector3();
  const _parentS = new Vector3();
  const _targetQ = new Quaternion();

  mesh.onBeforeRender = (renderer, scene, camera) => {
    _targetQ.copy(camera.quaternion);
    if (mesh.parent) {
      mesh.parent.updateWorldMatrix(false, false);
      mesh.parent.matrixWorld.decompose(_parentP, _parentQ, _parentS);
      _targetQ.premultiply(_parentQ.invert());
    }
    mesh.quaternion.copy(_targetQ);
  };

  group.add(mesh);

  let spriteTexture = null;
  const timelines = [];

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      spriteTexture = tex;

      const atlasW = tex.image?.width ?? region.w;
      const atlasH = tex.image?.height ?? region.h;

      const ux = (region.x ?? 0) / atlasW;
      const uy = (region.y ?? 0) / atlasH;
      const uSize = (region.w ?? 512) / atlasW;
      const vSize = (region.h ?? 320) / atlasH;

      tex.repeat.set(uSize, vSize);
      tex.offset.set(ux, 1 - uy - vSize);
      tex.needsUpdate = true;

      material.colorNode = texture(tex, uv());
      material.needsUpdate = true;
    });
  }

  group.userData.cleanup = () => {
    timelines.forEach((t) => t?.kill());
    geometry.dispose();
    material.dispose();
    if (spriteTexture) spriteTexture.dispose();
    mesh.onBeforeRender = null;
  };

  return group;
}
